"""Prevent comparisons between vectors generated by different embedding models."""

import sqlalchemy as sa

from alembic import op

revision = "0006"
down_revision = "0005"
branch_labels = None
depends_on = None


def upgrade():
    # Unknown legacy vectors require explicit local re-embedding, not a guessed model identity.
    """Add nonnull embedding_model with an empty legacy marker; unknown existing vectors require explicit
    reindexing rather than guessing which encoder produced them.
    """
    op.add_column("vector_chunks", sa.Column("embedding_model", sa.String(255), nullable=False, server_default=""))


def downgrade():
    """Reject loss of embedding identity with RuntimeError; a verified backup is required to restore the earlier
    model-comparison contract.
    """
    raise RuntimeError("Restore a verified backup to preserve embedding model identities")
